class Person {
    private val _courses = mutableListOf<Course>()

    val courses: List<Course> get() = _courses        // read-only view, no copy

    fun addCourse(course: Course) {
        require(course.accepted) { "course not accepted" }
        _courses += course
    }

    fun removeCourse(course: Course) { _courses -= course }
}
